745→<!-- Redirect links and searches when in dual view mode -->
746→<script>
747→document.addEventListener("DOMContentLoaded", function () {
748→  if (!window.location.pathname.startsWith("/dual")) return;
749→
750→  function getTargetPanel() {
751→    const selected = document.querySelector('input[name="targetPanel"]:checked');
752→    return selected ? selected.value : "left";
753→  }
